def on_live(store, event):
    old = store.get(event.job)
    if old is None or event.revision > old.revision:
        apply(store, event)

sources.catalog.py:
def quote(catalog, requested):
    index = {}
    for row in catalog:
        index.setdefault(row.sku, row)
    return [index.get(sku) for sku in requested]

sources.clean.py:
def clean(paths, apply=False):
    if not apply:
        return list(paths)
    for path in paths:
        path.unlink()
    return list(paths)

