sources.ranking.ts:
export function score(timestamp: number, now: number, base: number): number {
  const cutoff = now - 90 * 86400000;
  const age = now - timestamp;
  const recent = age < cutoff;
  return base * (recent ? 1.2 : 1.0);
}

export function score(timestamp: number, now: number, base: number): number {
  const cutoff = now - 90 * 86400000;
  const recent = timestamp >= cutoff && timestamp <= now;
  return base * (recent ? 1.2 : 1.0);
}

